import json
from pathlib import Path
r=Path(__file__).resolve().parents[1]
cases=[
('stream-submission','SubmitRequested on a fixed partition list','Open edition; valid authorized stream; required details; source version pinned','Assigned stream owner','Create protected versioned review snapshot','Retain draft and return redacted validation errors'),
('quality-review','Snapshot status Submitted','Authorized reviewer; exact submitted version; duplicates resolved explicitly','Data-quality reviewer','Record decision; promote through canonical participant resolver','Mark Rejected; publish safe correction reason'),
('arrival','Append-only arrival command','Approved participation; open edition; arrival not already recorded','Accommodation Team','Record independent arrival and actor timestamp','Keep prior arrival state; return reason'),
('accommodation','Append-only allocation command','Arrived; eligible; compatible room/bed; accessibility; no overlapping allocation','Accommodation Team','Reserve exclusive allocation and confirm check-in','Reject conflicting request without changing capacity'),
('identity-verification','Restricted verification request','Identity review permission; document purpose/minimization; correct participant','Authorized identity verifier','Publish verification status only','Record safe rejection status; restricted notes stay in vault'),
('registration','Registration command','Approved participation; required identity checklist; not departed; valid expected version','Registration Team','Set registered timestamp and desk; no accommodation prerequisite','Keep unregistered; publish actionable safe reason'),
('bank-verification','Restricted bank verification request','Approved bank boundary; required verification checks; distinct verifier where policy requires','Finance verifier','Publish masked verified reference only','Mark NeedsCorrection without leaking full bank details'),
('financial-approval','Claim Requested','Eligibility and limit rules; integer paise; maker != checker; reviewed claim version','Finance Checker','Append approval and authorized amount; no money transfer','Reject with restricted reason'),
('kit-issue','Kit command','Registered; entitled; not previously issued; sufficient ledger stock; approved replacement if applicable','Gifts & Kits Team','Commit one issue ledger row and decrease available stock','Reject duplicate/exhausted stock without decrement'),
('meal-service','Meal command','Active registration; matching entitlement/window/location; remaining capacity; not previously served','Food Team','Commit meal service and utilization ledger','Reject duplicate/ineligible/full request'),
('departure','Departure command','Arrived; no active stay; departure authorization; open edition','Accommodation or Transport Team','Confirm departure independently and release applicable resources','Keep prior state and explain unresolved stay'),
('reconciliation','Scheduled protected job','Incomplete receipt or ledger discrepancy; authorized service identity','Automation plus responsible supervisor','Resume from last durable stage; verify ledger/projections/audit; finalize receipt','Dead-letter protected correlation ID; require authorized repair')]
items=[]
for name,trigger,pre,approver,success,reject in cases:
 items.append(dict(name=name,status='specification-not-deployed',trigger=trigger,preconditions=pre,authorized_approver=approver,success_action=success,rejection_action=reject,notification='Protected outbox; safe record reference only; delivery may be duplicated after uncertain send',escalation='Configurable event-hours SLA to authorized supervisor; no sensitive payload',failure='Try/Catch; bounded 429/503 retry; honor Retry-After; dead-letter permission/validation errors; resume staged receipt',audit='Trusted actor object ID, UTC time, source version, action, correlation ID, outcome; no banking/identity/contact payload',idempotency='Unique server-derived request+stage keys; reject changed payload; ETag conditional writes',recovery='Prepared/Reserved/Committed receipt stages and scheduled reconciliation; SharePoint has no multi-list transaction'))
(r/'power-automate/workflows.json').write_text(json.dumps(items,indent=2)+'\n')
model={'status':'manual-desktop-build-required','fact_grain':'one participant per event edition','tables':{'FactParticipation':{'key':'ParticipationKey','integers':['Arrived','Registered','Departed','IsFirstYear']},'DimEdition':{'key':'EditionKey','integers':['Year'],'dates':['Starts','Ends']},'DimStream':{'key':'StreamKey'},'DimParticipant':{'key':'ParticipantKey'}},'relationships':[{'from':f'Dim{dim}.{key}','to':f'FactParticipation.{key}','cardinality':'one-to-many','direction':'single'} for dim,key in [('Edition','EditionKey'),('Stream','StreamKey'),('Participant','ParticipantKey')]],'filters':['Required selected edition','Authorized stream scope via tested RLS','State/district/category slicers within authorized model'],'excluded':['Identity documents','Bank details','Names','Phone','Email','Health','Community until approved aggregate projection'],'missing_facts':['Accommodation occupancy and dated capacity','Meals and entitlements','Trip utilization','Session attendance','Financial approvals/payments','Incidents and operational SLA','Expected arrival/departure forecasts']}
(r/'power-bi/model.json').write_text(json.dumps(model,indent=2)+'\n')
pages=[{'name':'Command center','visuals':['Participations','Approved','Registration Completion','Arrivals Confirmed','Departures Confirmed'],'filters':['Edition','Authorized streams'],'status':'initial participation facts only'}, {'name':'Participation and geography','visuals':['Participants by year/state/district/stream/category','Repeat versus first-time'],'filters':['Edition','State','District','Stream','Category'],'status':'sample pseudonymous data; privacy review required'}, {'name':'Historical comparison','visuals':['Participations trend','YoY Growth','Repeat Participations'],'filters':['Year range','Stream'],'status':'measures require complete history'}, {'name':'Operations','visuals':['Dated occupancy','Meal demand/utilization','Trip utilization','Venue attendance','Open issues'],'status':'not implemented; source facts required'}, {'name':'Finance — separate restricted report','visuals':['Approved assistance','Recorded external payments','Pending approved totals','Payment category/year'],'status':'not implemented; no bank/document fields permitted'}]
(r/'power-bi/report-pages.json').write_text(json.dumps(pages,indent=2)+'\n')
(r/'power-bi/theme.json').write_text(json.dumps({'name':'Sambad 360','dataColors':['#194F40','#A35D26','#E7B56C','#6B8791','#7E6B98','#577B46'],'background':'#F3F5F0','foreground':'#253E36','tableAccent':'#194F40'},indent=2)+'\n')
